    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Configura le impostazioni a livello di sistema: URL di base, sicurezza, lingua predefinita, fuso orario, valori predefiniti del punteggio del rischio e altro ancora.',
    'SettingsPreferencesDesc'             => 'Valori predefiniti e preferenze comportamentali in SimpleRisk: lingua, fuso orario, stato degli audit, requisiti di mappatura del rischio, opzioni di comportamento dell\'interfaccia utente e simili.',
    'SettingsFileUploadDesc'              => 'Tipi di file consentiti per il caricamento e limiti di dimensione per i vari campi di allegato file.',
    'SettingsMailDesc'                    => 'Configurazione SMTP per le notifiche email in uscita, inclusi trasporto, host, autenticazione e indirizzo di risposta.',
    'SettingsBackupsDesc'                 => 'Configura la conservazione dei backup, la pianificazione e i link per il download dei backup del database di SimpleRisk.',
    'SettingsSecurityDesc'                => 'Autenticazione, sessione, criteri password, URL di base e impostazioni di sicurezza API.',
    'SettingsLoggingDesc'                 => 'Configurazione dei registri di debug e di audit: livelli di registro, conservazione e posizione dei file di registro.',
    'HealthCheckDesc'                     => 'Diagnostica lo stato del sistema: versione di PHP, estensioni, autorizzazioni dei file, connettività del database, pianificazione cron e attivazioni degli Extra.',
    'AnnouncementsDesc'                   => 'Crea e gestisci gli annunci in banner visibili a tutti gli utenti.',
    'RegisterAndUpgradeDesc'              => 'Registra la tua installazione di SimpleRisk, inserisci o rinnova una chiave di abbonamento e avvia gli aggiornamenti Core/Extra con un solo clic.',
    'QueueMonitorDesc'                    => 'Esamina la coda dei processi in background: processi in sospeso, in corso e non riusciti.',
    'ExtrasDesc'                          => 'Attiva, disattiva e configura gli Extra di SimpleRisk (componenti aggiuntivi a pagamento).',
    'ArtificialIntelligenceExtraDesc'     => 'La funzionalità Intelligenza Artificiale Extra offre un\'analisi del rischio più avanzata (incluse le valutazioni FAIR) e una documentazione personalizzata.',
    'CustomizationExtraDesc'              => 'La funzionalità Extra di personalizzazione consente di aggiungere e rimuovere diversi tipi di campi e di creare dinamicamente modelli di pagina personalizzati.',
    'NotificationExtraDesc'               => 'L\'Extra Email Notification consente a SimpleRisk di inviare notifiche email quando i rischi vengono inseriti, modificati o comunque trattati. Questo Extra può inoltre essere aggiunto come script pianificato per inviare promemoria periodici quando i rischi sono pronti per una revisione della gestione. Nel prodotto SimpleRisk Core, senza questo Extra, nessuna notifica viene comunicata all\'esterno dello strumento stesso.',
    'VulnerabilityManagementExtraDesc'    => 'Il pacchetto Vulnerability Management Extra offre ai clienti la possibilità di integrare la propria istanza di SimpleRisk con Qualys, Tenable.io o Rapid7 Nexpose/InsightVM e importare dati relativi ad asset e vulnerabilità in SimpleRisk. Da lì, è possibile selezionare i siti da monitorare, determinare quali punteggi di vulnerabilità importare e classificare le vulnerabilità da trasformare in rischi per il loro tracciamento.',
    'IncidentManagementExtraDesc'         => 'Incident Management Extra si basa sulla guida NIST 800-61 per la gestione degli incidenti di sicurezza informatica e offre funzionalità di gestione degli incidenti direttamente all\'interno del sistema SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Rinomina la terminologia di SimpleRisk (rischio, asset, framework, ecc.) in tutta l\'interfaccia.',
    'RiskConfigurationDesc'               => 'Configura le regole di punteggio del rischio: livelli, propensione al rischio, soglie SLA e formule di rischio classica / con fattori contribuenti.',
    'RiskAndThreatCatalogDesc'            => 'Gestire il catalogo dei valori di rischio e minaccia utilizzati nei menu a tendina.',
    'AddAndRemoveValuesDesc'              => 'Gestisci i valori dei menu a tendina per i campi di rischio: posizione, origine, categoria, team, tecnologia e altro ancora.',
    'AssetValuationDesc'                  => 'Configura la scala di valutazione degli asset e le eccezioni di valutazione per singolo asset.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Aggiungere, modificare, disabilitare e reimpostare gli utenti; gestire le policy relative alle password.',
    'RoleManagementDesc'                  => 'Definisci i ruoli e le autorizzazioni che ciascun ruolo concede.',
    'TeamManagementDesc'                  => 'Creare e gestire i team utilizzati per il filtraggio della visibilità dei record.',
    'SeparationExtraDesc'                 => 'L\'Extra Team-Based Separation limita la visualizzazione dei rischi ai soli utenti che sono membri del team a cui il rischio è assegnato. Nel prodotto SimpleRisk Core, senza questo Extra, ogni utente può visualizzare ogni rischio.',
    'CustomAuthenticationExtraDesc'       => 'Il componente aggiuntivo Autenticazione personalizzata offre supporto per Active Directory e autenticazione SAML. Nel prodotto SimpleRisk Core, senza questo componente aggiuntivo, l\'unica opzione è creare nuovi utenti nel repository di identità di SimpleRisk.',
    'EncryptionExtraDesc'                 => 'L\'Extra Encrypted Database genera una chiave di crittografia AES-256 bit casuale e la utilizza per crittografare il testo sensibile prima che venga inserito nel database di SimpleRisk. Questo impedisce a chiunque di visualizzare o modificare i dati senza utilizzare direttamente l\'applicazione SimpleRisk.',
    'OrganizationManagementDesc'          => 'L\'Extra Organizational Hierarchy consente di definire più Business Unit che possono includere un numero qualsiasi di team. Gli utenti possono quindi essere assegnati a uno o più team all\'interno di varie Business Unit. Ciò influisce sulla capacità di un utente di visualizzare e utilizzare i team, gli utenti e gli asset a cui non è associato.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Elimina i rischi in blocco. Usare con cautela: le eliminazioni sono permanenti.',
    'AuditTrailDesc'                      => 'Cerca ed esporta il registro di audit di sistema delle azioni degli utenti.',
    'ImportExportExtraDesc'               => 'L\'Extra Import-Export offre la possibilità di importare dati in SimpleRisk mappando i campi di un file CSV sui campi del database di SimpleRisk. Può essere utilizzato per importare risultati di audit da un foglio di calcolo di terze parti, risultati di scansione delle vulnerabilità da un altro strumento, asset dal proprio CMDB e altro ancora. L\'Extra consente inoltre di esportare da SimpleRisk file CSV contenenti rischi, mitigazioni, revisioni o un report combinato di tutti e tre.',
    'JiraExtraDesc'                       => 'L\'Extra Jira Integration offre agli utenti la possibilità di integrarsi in modo bidirezionale con un\'istanza di Jira. Consente di collegare i rischi ai problemi di Jira, nonché di sincronizzarne dati, stato e commenti.',
    'APIExtraDesc'                        => 'L\'Extra API consente ai clienti di utilizzare un\'API RESTful per creare interazioni con script con altre applicazioni, ottenendo un\'automazione avanzata e sfruttando l\'infrastruttura esistente.',
    'AdvancedSearchExtraDesc'             => 'L\'Extra Advanced Search trasforma la casella di ricerca della barra superiore in un\'unica ricerca su rischi, framework, controlli, documenti, eccezioni, test, audit, asset e gruppi di asset, con una pagina di ricerca completa per lavorare sui risultati. Mostra solo i record che l\'utente è autorizzato a visualizzare.',
    'AssessmentsExtraDesc'                => 'L\'Extra Risk Assessment offre agli utenti la possibilità di definire contatti, creare domande (inclusa la logica), assemblare più domande con un modello di questionario, creare questionari e inviarli ai contatti, visualizzare i risultati del questionario, aggiungere rischi in base a tali risultati, confrontare i risultati nel tempo, importare ed esportare valutazioni personalizzate esternamente e rivedere l\'audit trail della valutazione del rischio.',
    'ActiveAssessmentsDesc'               => 'Visualizza e gestisci le valutazioni attualmente in corso.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra offre un motore di workflow visivo e basato sugli eventi che automatizza le azioni di gestione del rischio in risposta agli eventi all\'interno di SimpleRisk. È possibile progettare workflow che si attivano in seguito a modifiche, come l\'invio, l\'aggiornamento o la revisione di un rischio, per instradare le approvazioni, assegnare il lavoro e mantenere il processo in movimento senza intervento manuale.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'L\'Extra Secure Controls Framework (SCF) è un\'integrazione diretta tra il Secure Controls Framework e SimpleRisk. Importa in SimpleRisk, nella funzionalità Governance, il catalogo dei controlli dell\'SCF e le relative mappature su un\'ampia gamma di framework di conformità e di cybersecurity, in modo da poter adottare i framework di cui hai bisogno e gestirne i controlli senza doverli creare manualmente.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migra le colonne varchar legacy delle date di revisione ai tipi data appropriati. Visibile solo quando necessario.',
    'DatabaseUpgradeDesc'                 => 'Avviare manualmente la procedura di aggiornamento del database di SimpleRisk.',

