    'AssetScoring' => 'Punteggio degli asset',
    'AssetScoringSettingsHint' => 'Ogni asset viene valutato Basso, Moderato o Alto per riservatezza, integrità e disponibilità; la riservatezza può invece essere Non applicabile, e in tal caso viene esclusa da entrambi i risultati. La sua categorizzazione FIPS è la più alta delle tre valutazioni. Il suo punteggio ponderato è la media ponderata dei tre valori di livello e le soglie delle fasce trasformano tale punteggio in una fascia bassa, moderata o alta. La modifica di queste impostazioni ricalcola immediatamente il punteggio di ogni asset.',
    'Weights' => 'Pesi',
    'AssetScoringWeightsHint' => 'Quanto conta ogni obiettivo nel punteggio ponderato: da 0 a 100, con un massimo di due decimali. Un peso pari a 0 esclude l\'obiettivo. Integrità e Disponibilità non possono essere entrambe 0, perché una riservatezza Non applicabile viene sempre esclusa.',
    'LevelValues' => 'Valori dei livelli',
    'AssetScoringLevelValuesHint' => 'Il numero che ogni valutazione apporta al punteggio ponderato: maggiore di 0 e fino a 100, con un massimo di due decimali, e Basso inferiore a Moderato inferiore ad Alto. I valori predefiniti sono Basso 1, Moderato 2 e Alto 3.',
    'BandThresholds' => 'Soglie delle fasce',
    'AssetScoringBandThresholdsHint' => 'Un punteggio ponderato pari o superiore a una soglia rientra in quella fascia, mentre un punteggio inferiore alla soglia Moderato è Basso. Moderato deve iniziare sopra il valore Basso, e Alto deve iniziare sopra Moderato e non oltre il valore Alto.',
    'ModerateStartsAt' => 'Il livello moderato inizia a',
