    'AssetScoringDefaultsHint' => 'Preseleziona queste valutazioni quando qualcuno aggiunge un asset nel modulo dell\'asset. Gli asset creati tramite discovery, importazione o API restano senza punteggio, a meno che non forniscano le proprie valutazioni. Lascia tutti e tre su Non impostato per disattivare questa funzione.',
    'AssetScoringWeightsInvalid' => 'I pesi del punteggio degli asset devono essere numeri da 0 a 100 con al massimo due decimali, e Integrità e Disponibilità non possono essere entrambe 0.',
