    'AssetScoringScoreHelp' => 'Il punteggio ponderato combina le tre valutazioni in un unico numero compreso tra {$low} e {$high}. Ogni valutazione diventa il rispettivo valore impostato e viene moltiplicata per il peso del relativo obiettivo. I risultati vengono sommati e divisi per il totale dei pesi. Una Riservatezza Non applicabile viene esclusa, insieme al suo peso. I valori impostati e i pesi sono configurati in Preferenze. Tutti e tre gli obiettivi devono essere valutati prima che venga mostrato un punteggio.',
    'AssetScoringCategorizationHelp' => 'La categorizzazione di sicurezza FIPS 199 corrisponde al livello massimo (high-water mark): la valutazione più alta tra gli obiettivi applicabili. Una sola valutazione "Alto" rende l\'asset "Alto", indipendentemente dalle altre. "Non applicabile" viene ignorato.',
