    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Abilita HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Indica ai browser di connettersi a SimpleRisk solo tramite HTTPS per la durata massima indicata di seguito. Abilitare solo dopo aver verificato che HTTPS funzioni in modo affidabile su questo sito: i browser che hanno ricevuto l\'intestazione rifiuteranno HTTP semplice e un certificato non valido non può essere aggirato fino alla scadenza della durata massima. Iniziare con una durata breve, ad esempio 300 secondi, e aumentarla una volta verificato HTTPS.',
